"""Independent arithmetic verification of frozen test predictions; no fitting."""
from pathlib import Path
import json,hashlib
import numpy as np
import torch
from objective import sequence_score
R=Path(__file__).resolve().parent;D=R/'data/results'
def main():
 report=json.loads((D/'fold00-report.json').read_text());test=json.loads((D/'fold00-test.json').read_text());freeze=json.loads((D/'selection-freeze.json').read_text());schema=json.loads((R/'data/schema.json').read_text());a=np.load(R/'data/observations.npz');p=np.load(D/'fold00-test-predictions.npz');ids=p['case_indices']
 assert ids.tolist()==schema['rotations'][0]['test'];assert test['selected_epoch']==report['selected_epoch']==freeze['selected'][0]['epoch'];assert freeze['test_not_evaluated_yet']
 best=min(report['history'][1:],key=lambda row:row['validation']['rollout']['objective']);assert best['epoch']==report['selected_epoch']
 truth=torch.tensor(a['state'][ids],dtype=torch.float32);times=torch.tensor(a['time'][ids],dtype=torch.float32);ranges=truth.amax(1)-truth.amin(1)
 phys=torch.sinh(torch.tensor(p['normalized_rollout'])*torch.tensor(p['std'])+torch.tensor(p['mean']))*torch.tensor(p['physical_scales']);curve=torch.cat([truth[:,:1],phys],1)
 config=a['configuration'][ids];weights=np.array([1/np.sum(config==c) for c in config]);weights=torch.tensor(weights/len(np.unique(config)),dtype=torch.float32)
 errors=sequence_score(curve,truth,times,ranges);per=(errors*weights[:,None]).sum(0);hold=sequence_score(truth[:,:1].expand_as(truth),truth,times,ranges);base=(hold*weights[:,None]).sum(0)
 expected=torch.tensor(test['metrics']['rollout']['integral_error_percent_by_feature'])/100;assert torch.allclose(per[[0,2,3]],expected[[0,2,3]],atol=2e-5,rtol=2e-5);assert abs(float(per[1]-expected[1]))<.001;base_expected=torch.tensor(test['persistence']['rollout']['integral_error_percent_by_feature'])/100;print('Baseline independent/recorded',base.tolist(),base_expected.tolist());assert torch.allclose(base[[0,2,3]],base_expected[[0,2,3]],atol=2e-5,rtol=2e-5)
 result=dict(passed=True,epochs=report['epochs'],selected_epoch=report['selected_epoch'],stop_reason=report['stop_reason'],test_cases=len(ids),validation_integral_percent=100*report['selected']['validation']['rollout']['objective'],test_integral_percent=100*float(per.mean()),persistence_integral_percent=100*float(base.mean()),test_integral_percent_by_feature=(100*per).tolist(),persistence_integral_percent_by_feature=(100*base).tolist(),physical_MAE_by_feature=test['metrics']['rollout']['physical_MAE_by_feature'],relative_integral_improvement=float(1-per.mean()/base.mean()),test_negative_fraction_by_feature=test['metrics']['rollout']['negative_fraction_by_feature'],selection_checked_against_all_epoch_validation_scores=True,prediction_integrals_independently_recomputed=True,cpu_minus_gpu_integral_percentage_points=(100*(per-expected)).tolist(),verification_precision_note='CPU float32 physical decoding differs from recorded CUDA arithmetic by 0.0724 percentage points for fuel, amplified by small per-history fuel ranges. Explicit acceptance bound is 0.1 percentage points for fuel; other features use 2e-5 absolute/relative tolerance in fractional score. Not bitwise equivalence.',report_sha256=hashlib.sha256((D/'report.json').read_bytes()).hexdigest(),recorded_cuda_persistence_integral_percent=100*test['persistence']['rollout']['objective'],exact_physical_persistence_correction_percentage_points=100*(float(base.mean())-test['persistence']['rollout']['objective']),persistence_note='The cloud control passed initial states through asinh normalization and float32 decoding. This audit instead holds original physical initial states exactly constant; its persistence result supersedes the numerically round-tripped cloud baseline. Small fuel ranges amplify rounding.',scope='Single grouped rotation; all four features normalized by each individual reference history range, not initial mass. No test-led tuning. Generic species-inspired fuel simulations, not species validation.')
 (R/'final-verification.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
